def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the repeated color key: a nonzero row repeated vertically.
    key = None
    for r in range(h):
        row = tuple(grid[r])
        if 0 in row or len(set(row)) < 2:
            continue
        run = 1
        while r + run < h and tuple(grid[r + run]) == row:
            run += 1
        if run >= 2 and (key is None or len(row) * run > key[0]):
            key = (len(row) * run, r, run, row)
    if key is None:
        return [list(row) for row in grid]
    _, kr, kh, colors = key
    colors = list(colors)
    kc0 = next(c for c, v in enumerate(grid[kr]) if v != 0)
    kc1 = max(c for c, v in enumerate(grid[kr]) if v != 0)
    keycells = {(r, c) for r in range(kr, kr + kh) for c in range(kc0, kc1 + 1)}

    # Collect same-color connected components outside the key.
    comps = []
    for color in set(colors):
        cells = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color and (r, c) not in keycells}
        while cells:
            seed = cells.pop()
            comp = {seed}
            q = [seed]
            while q:
                r, c = q.pop()
                for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if p in cells:
                        cells.remove(p); comp.add(p); q.append(p)
            rs = [p[0] for p in comp]; cs = [p[1] for p in comp]
            r0, c0 = min(rs), min(cs)
            sig = frozenset((r-r0, c-c0) for r,c in comp)
            comps.append((color, r0, c0, sig))

    # The repeated object has the same shape in each keyed color.
    groups = {}
    for color, r0, c0, sig in comps:
        groups.setdefault(sig, []).append((color, r0, c0))
    if not groups:
        return [list(row) for row in grid]
    sig, copies = max(groups.items(), key=lambda item: (len(item[1]), len(item[0])))
    # A single visible copy is enough; use its position in the key to align the stack.
    valid = [(colors.index(color), r0, c0) for color, r0, c0 in copies if color in colors]
    if not valid:
        return [list(row) for row in grid]
    idx, r0, c0 = valid[0]
    motif_h = max(r for r, c in sig) + 1
    top = r0 - idx * motif_h

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(colors):
        for dr, dc in sig:
            rr, cc = top + i * motif_h + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
